6	export default tool({
7	  description: "Archive experiment worktrees from /tmp into git history under refs/experiments/. Safe by default — never deletes without explicit confirmation.",
8	  args: {
9	    pattern: tool.schema.enum(["exp", "story", "all"]).optional().default("all"),
10	    remove_after: tool.schema.boolean().optional().default(false),
11	    dry_run: tool.schema.boolean().optional().default(true),
12	  },
13	  async execute(args, ctx) {
14	    const tmpDir = "/tmp"
15	    const globs = args.pattern === "all"
16	      ? ["exp_*", "story_*"]
17	      : [`${args.pattern}_*`]
18	
19	    let entries: string[] = []
20	    try {
21	      entries = readdirSync(tmpDir)
22	    } catch {
23	      return "Cannot read /tmp"
24	    }
25	
26	    const matches: { name: string; hasGit: boolean }[] = []
27	    for (const entry of entries) {
28	      const matchPattern = globs.some((g) => {
29	        const regex = new RegExp("^" + g.replace("*", ".*") + "$")
30	        return regex.test(entry)
31	      })
32	      if (!matchPattern) continue
33	      const fullPath = join(tmpDir, entry)
34	      if (!existsSync(join(fullPath, ".git"))) continue
35	      matches.push({ name: entry, hasGit: true })
36	    }
37	
38	    if (matches.length === 0) {
39	      return `No ${args.pattern} worktrees with git history found in /tmp.`
40	    }
41	
42	    if (args.dry_run) {
43	      const lines = [`Dry run: ${matches.length} worktrees would be archived to refs/experiments/:`]
44	      for (const m of matches) {
45	        lines.push(`  ${m.name}`)
46	      }
47	      if (!args.remove_after) {
48	        lines.push(`\nWorktrees will be preserved in /tmp after archiving (remove_after=false).`)
49	      } else {
50	        lines.push(`\nWorktrees WILL be removed from /tmp after archiving (remove_after=true).`)
51	      }
52	      lines.push(`\nRun with dry_run=false to execute.`)
53	      return { output: lines.join("\n"), metadata: { count: matches.length } }
54	    }
55	
56	    const archived: string[] = []
57	    const skipped: string[] = []
58	    const errors: string[] = []
59	
60	    for (const m of matches) {
61	      const refName = `refs/experiments/${m.name}`
62	      const worktreePath = join(tmpDir, m.name)
63	
64	      // Check if this ref already exists (skip re-archive)
65	      try {
66	        execSync(`git show-ref --verify --quiet "${refName}"`, { encoding: "utf-8", cwd: ctx.directory })
67	        skipped.push(`${m.name} (already archived)`)
68	        continue
69	      } catch {
70	        // ref doesn't exist, proceed
71	      }
72	
73	      // Check if worktree has any commits
74	      let hasCommits = false
75	      try {
76	        const branch = execSync(`git -C "${worktreePath}" rev-parse --abbrev-ref HEAD`, { encoding: "utf-8" }).trim()
77	        execSync(`git -C "${worktreePath}" rev-parse --verify HEAD`, { encoding: "utf-8" })
78	        try {
79	          execSync(`git fetch "${worktreePath}" "+${branch}:${refName}"`, { encoding: "utf-8", cwd: ctx.directory })
80	          archived.push(m.name)
81	          hasCommits = true
82	        } catch (e) {
83	          errors.push(`${m.name}: fetch failed (${(e as Error).message.slice(0, 80)})`)
84	        }
85	      } catch {
86	        skipped.push(`${m.name} (no commits)`)
87	      }
88	
89	      // Optionally remove worktree from /tmp
90	      if (hasCommits && !errors.includes(m.name) && args.remove_after) {
91	        try {
92	          execSync(`rm -rf "${worktreePath}"`, { encoding: "utf-8" })
93	        } catch {
94	          // not fatal
95	        }
96	      }
97	    }
98	
99	    const lines: string[] = []
100	    if (archived.length > 0) {
101	      lines.push(`Archived ${archived.length} worktrees to refs/experiments/.`)
102	      lines.push(`  Browse: git log refs/experiments/{name}`)
103	      lines.push(`  List all: git for-each-ref refs/experiments/`)
104	    }
105	    if (skipped.length > 0) {
106	      lines.push(`Skipped ${skipped.length}: ${skipped.join(", ")}`)
107	    }
108	    if (errors.length > 0) {
109	      lines.push(`Errors (${errors.length}): ${errors.join("; ")}`)
110	    }
111	    if (args.remove_after && archived.length > 0) {
112	      lines.push(`Removed ${archived.length} worktrees from /tmp.`)
113	    }
114	
115	    return {
116	      output: lines.join("\n") || "Archive completed.",
117	      metadata: { archived: archived.length, skipped: skipped.length, errors: errors.length },
118	    }
119	  },
120	})
